function paintRatingSummary(target,average,total){const count=Number(total)||0,score=Math.max(0,Math.min(5,Math.round(Number(average)||0))),stars=`${'★'.repeat(score)}${'☆'.repeat(5-score)}`;target.hidden=false;target.dataset.ratingAverage=String(Number(average)||0);target.dataset.ratingTotal=String(count);target.classList.toggle('is-empty',count===0);target.innerHTML=count?`<span class="rating-stars" aria-label="${Number(average||0).toFixed(1)} de 5 estrelas">${stars}</span><small>(<b>${count}</b>)</small>`:'<span class="rating-stars" aria-hidden="true">☆☆☆☆☆</span><small>Ainda sem avaliações</small>'}
