function bindListingFilters(){
  const state=window.__shoplabListing;if(!state)return;
  if(state.premiumSearch?.enabled){const summary=$('#listing-summary');if(summary&&!document.querySelector('.premium-search-insight'))summary.insertAdjacentHTML('afterend',`<div class="premium-search-insight"><span>SHOPLAB+ · BUSCA INTELIGENTE</span><strong>Melhores opções primeiro</strong><p>${esc(state.premiumSearch.explanation||'Resultados organizados por adequação à busca, qualidade e custo-benefício.')}</p></div>`)}
  const category=$('#category'),min=$('#min-price'),max=$('#max-price'),promotion=$('#promotions-only'),sort=$('#sort'),grid=$('#listing-products'),empty=$('#empty-results');
  const render=()=>{
    if(Number(min.value)>Number(max.value)){if(document.activeElement===min)max.value=min.value;else min.value=max.value}
    $('#min-price-label').textContent=money(Number(min.value));$('#max-price-label').textContent=money(Number(max.value));
    const range=Number(state.priceCeil)-Number(state.priceFloor)||1,left=(Number(min.value)-state.priceFloor)/range*100,right=(Number(max.value)-state.priceFloor)/range*100;
    min.parentElement.style.setProperty('--range-start',`${left}%`);min.parentElement.style.setProperty('--range-end',`${right}%`);
    let products=state.products.filter(product=>(!category.value||product.category===category.value)&&Number(product.price)>=Number(min.value)&&Number(product.price)<=Number(max.value)&&(!promotion.checked||Number(product.discount)>0||Number(product.oldPrice)>Number(product.price)||product.promotionEndsAt));
    products=[...products].sort((a,b)=>sort.value==='price-asc'?a.price-b.price:sort.value==='price-desc'?b.price-a.price:sort.value==='discount'?(Number(b.discount)||0)-(Number(a.discount)||0):0);
    grid.innerHTML=products.map(state.card).join('');empty.hidden=products.length>0;$('#result-count').textContent=`${products.length} ${products.length===1?'resultado':'resultados'}`;$('#listing-summary').textContent=`${products.length} ${products.length===1?'produto encontrado':'produtos encontrados'} · resultados disponíveis.`;
    const url=new URL(location.href);[['category',category.value],['minPrice',min.value==state.priceFloor?'':min.value],['maxPrice',max.value==state.priceCeil?'':max.value],['promotion',promotion.checked?'1':''],['sort',sort.value]].forEach(([key,value])=>value?url.searchParams.set(key,value):url.searchParams.delete(key));history.replaceState(null,'',url);
  };
  [category,min,max,promotion,sort].forEach(control=>control?.addEventListener(control.type==='range'?'input':'change',render));
  const clear=()=>{category.value='';min.value=state.priceFloor;max.value=state.priceCeil;promotion.checked=false;sort.value='';render()};
  $('#clear-filters').onclick=clear;$('[data-clear-filters]')?.addEventListener('click',clear);render();
}
