async function loadProductRecommendations(){const target=document.querySelector('#product-related'),slug=params.get('slug');if(!target||!slug)return;const wait=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));for(let attempt=0;attempt<3;attempt+=1){try{if(attempt)await wait(attempt*700);const products=await getRecommendations(slug);if(!products.length)throw new Error('Nenhuma alternativa recebida');target.innerHTML=section('Produtos relacionados','Outras opções analisadas pelo laboratório.',products);await bindLibraryUI();await bindRatingSummaries().catch(()=>null);bindProductImpressions();return}catch(error){if(attempt===2)target.innerHTML='<section class="section related-loading"><div class="container"><span class="eyebrow">SHOPLAB+ · CURADORIA</span><h2>Não foi possível carregar as alternativas</h2><button class="btn ghost" type="button" data-retry-related>Tentar novamente</button></div></section>'}}target.querySelector('[data-retry-related]')?.addEventListener('click',()=>{target.innerHTML='<section class="section related-loading"><div class="container"><span class="eyebrow">SHOPLAB+ · CURADORIA</span><h2>Buscando alternativas próximas…</h2></div></section>';loadProductRecommendations()},{once:true})}
